INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(474200, 0, 4742, 0, 0, 15, 'Hrothgar''s Landing', 'Hrothgar''s Landing is a small island in the North Sea, across the strait called the Sea Reaver''s Run from the northern shore of Icecrown. From the grounds of the Argent Tournament it can be seen to the north, shrouded in mist, and the same mist lies heavy over the island and the strait. It was a tuskarr settlement until the Kvaldir came: seafaring vrykul raiders who sail out of the fog, whom the tuskarr call the walkers of the fog. They slew the Tualiq villagers, left them lying where they fell, and renamed the island Hrothgar''s Landing. Their leader is Drottinn Hrothgar, a veteran raider. Kvaldir reavers and mist binders now hold its hills and shores, a raider ship lies at anchor at the eastern end of its harbor, and in the northeast a circle of old tuskarr statues still stands. Cargo the raiders have stolen lies scattered across the island, and the tournament fears its own grounds will be their next target.', 'quest 14074 description (island to the north, seen shrouded in mist from the grounds; ship''s cargo taken there); quest 14080 description (Kvaldir murdered the tuskarr inhabitants and renamed the island Hrothgar''s Landing; the tournament their next target); quest 14101 description (kvaldir are seafaring vrykul; their leader the veteran raider Drottinn Hrothgar; circle of tuskarr statues in the northeast); quest 14104 description (Ornolf''s ship at anchor at the eastern end of the island''s harbor); spell_area: spell 68085 Mist of the Kvaldir (screen effect) on 4742 and 4760 for everyone, no quest (wowhead spell 68085); zone_areas 4742: Kvaldir Reaver 34838, Kvaldir Mist Binder 34839, Slain Tualiq Villager 34852, Stolen Tallstrider Leg 195274; gameobjects 195328 Tualiq Monuments (10404,939) and 195330 Deck of the Bor''s Fury (10004,645), posarea 4742; borean.json 353707 and 353721 (the tuskarr call the Kvaldir walkers of the fog); warcraft.wiki.gg/wiki/Kvaldir (tuk-hariq); warcraft.wiki.gg/wiki/Hrothgar''s_Landing (island north of Icecrown across the Sea Reaver''s Run; tuskarr village conquered and renamed)'),
(474201, 1, 4742, 1, 0, 15, 'The Sea Reaver''s Run', 'The Sea Reaver''s Run is the strait between Hrothgar''s Landing and the Argent Tournament Grounds, and the Kvaldir mist hangs over it as thickly as over the island. Two ships are locked in battle there. On the western side lies the Sunreavers'' Firehawk under the blood elf Captain Aerthas Firehawk, and on the eastern side the Silver Covenant''s Wavecrest under the high elf Captain Elleane Wavecrest. Kvaldir berserkers and harpooners have boarded both, and the bodies of mariners and raiders lie together on the decks while the crews fight on. Between them, Kvaldir deepcallers stand aboard a raiding vessel in the middle of the strait, and the North Sea Kraken rises among the ships.', 'zone_areas 4760: Captain Aerthas Firehawk 35090, Firehawk Mariner 35070 and dead mariners 35079/35083, Captain Elleane Wavecrest 35102, Wavecrest Mariner 35098 and dead mariners 35104/35105, Kvaldir Berserker 34947, Kvaldir Harpooner 34907 and their dead 35080/35084, Kvaldir Deepcaller 35092, North Sea Kraken 34925 (all phase 1); quest 14136 description (the Firehawk on the western side of the Sea Reaver''s Run, between the island and the grounds); quest 14152 description (the Wavecrest on the east side of the pass); quest 14108 description (ships detained by a Kvaldir raiding vessel; the kraken beneath the North Sea); spell_area 68085 Mist of the Kvaldir on 4760; warcraft.wiki.gg/wiki/Captain_Aerthas_Firehawk (blood elf, Sunreavers); warcraft.wiki.gg/wiki/Captain_Elleane_Wavecrest (high elf, Silver Covenant); only their Wrath-era pages used; warcraft.wiki.gg/wiki/Kvaldir_Deepcaller (on the kvaldir raiding vessel in the middle of Sea Reaver''s Run)'),
(474202, 2, 4742, 1, 0, 15, 'Drottinn Hrothgar', 'Drottinn Hrothgar leads the Kvaldir who overran the tuskarr island across the strait from the Argent Tournament, the island that now bears his name. He is a veteran raider among seafaring vrykul who prey on ships and coastal settlements, and he means to make himself master of these seas. While he rules them, the Argent Crusade fears that none of its supply ships or troop transports will be safe, and that its crusaders will be left stranded in Icecrown at the Lich King''s mercy. High Crusader Adelard has a captured Kvaldir war horn for the champion who will carry it to the circle of tuskarr statues in the northeast of the island and sound it there as a challenge.', 'quest 14101 description; creature_template 34980 subname The Sea Reaver; gameobject 195328 Tualiq Monuments (spell focus for the horn), posarea 4742; warcraft.wiki.gg/wiki/Drottinn_Hrothgar (kvaldir, The Sea Reaver, took the island from the tuskarr; added 3.2.0); warcraft.wiki.gg/wiki/Drottinn_Hrothgar (kvaldir raider who claimed Hrothgar''s Landing from the local tuskarr)'),
(474203, 2, 4742, 2, 0, 15, 'Mistcaller Yngvar', 'Mistcaller Yngvar is one of the Kvaldir who have returned to the coasts of Northrend. He has made his lair in a cave on the western side of Hrothgar''s Landing, and from there he works the mists that conceal the raiders and the sea beasts they command, so that they can fall on the crusade''s supplies and reinforcements unseen. He keeps himself hidden as well: High Crusader Adelard gives a charm to the champion who will cross the strait, find the mistcaller''s cave and use the charm to reveal him.', 'quest 14102 description; gameobjects 195329 Mistcaller''s Cave (spell focus) and 195318 Mistcaller''s Brazier at 10185,1185, posarea 4742; smart_scripts 34965 (Call of the Mist out of combat, Mist of Strangulation in combat)'),
(474204, 2, 4742, 3, 0, 15, 'Ornolf the Scarred', 'Ornolf the Scarred is a fearsome raider, renowned among the Kvaldir for taking ships. From the deck of his own vessel, Bor''s Fury, he and his crew fall upon the crusade''s ships and carry off their goods, and they were among those who slaughtered the tuskarr of the island and renamed it Hrothgar''s Landing. Bor''s Fury now lies at anchor at the eastern end of the island''s harbor. High Crusader Adelard means to draw Ornolf out with a captured Kvaldir banner, raised on his own ship for him to see.', 'quest 14104 description; gameobject 195330 Deck of the Bor''s Fury (spell focus for the banner) at 10004,645, posarea 4742'),
(474205, 3, 4742, 1, 0, 15, 'Stop the Aggressors', 'The Kvaldir do not keep to their island. A fast Argent Crusade ship carrying tallstrider meat and other supplies to the tournament never arrived: scouts saw the raiders fall on it, kill its crew and carry the cargo off to Hrothgar''s Landing, and without it the tournament will soon run short of food. The same raiders have murdered the island''s tuskarr, and if they gain a foothold there, the grounds across the strait will surely be next. The crusade''s own forces have their hands full with the Scourge, so the Silver Covenant''s Narasi Snowdawn and the Sunreavers'' Girana the Blooded, rivals in all else, both send champions north to win back the stolen supplies and strike at the Kvaldir before they can destroy anything more.', 'quests 14074 and 14143 descriptions (the supply ship, its crew slain, cargo taken to the island); quests 14080 and 14140 descriptions (tuskarr murdered; foothold; crusade busy with the Scourge); quests 14080 and 14140 reward text (each order calls itself the better ally to the crusade); creature_template 34880 subname The Silver Covenant, 34771 The Sunreavers'),
(474206, 3, 4742, 2, 0, 15, 'The Light''s Mercy', 'The tuskarr of Hrothgar''s Landing still lie where the Kvaldir cut them down, and the mists that engulf the island keep their spirits from finding peace. At the tournament, Narasi Snowdawn of the Silver Covenant and Girana the Blooded of the Sunreavers have both been listening to Argent Confessor Paletress, and her words have moved them to learn from the crusaders as well as fight beside them. Each now sends champions across the strait with a prayer book from the confessor, to read the rites for the dead over the slain villagers so that their spirits may escape the mist.', 'quest 14077 description (Narasi: take up the crusaders'' mission; rites let the spirits escape the mists); quest 14144 description (Girana: we can learn from them, too); item 46870 Confessor''s Prayer Book (start item of 14077); zone_areas 4742: Slain Tualiq Villager 34852 x47'),
(474207, 3, 4742, 3, 0, 15, 'Rescue at Sea', 'The Sunreavers and the Silver Covenant did not wait for the Kvaldir to come to them. Each sent a ship north to strike at Hrothgar''s Landing: the Sunreavers sent the Firehawk under Captain Aerthas Firehawk, and the Silver Covenant the Wavecrest under Captain Elleane Wavecrest. Neither reached the island. In the Sea Reaver''s Run both ran into a Kvaldir raiding party bound for the tournament grounds, and now berserkers and harpooners swarm their decks, far outnumbering the crews and slowly taking the ships from them. Champions are sent out over the water to fight beside the mariners.', 'quest 14136 description (Girana: the Firehawk under attack, vastly outnumbered); quest 14152 description (Narasi: the Wavecrest intercepted by a raiding party headed for the grounds, slowly being taken); quest 14108 description (both orders sent ships north to engage the Kvaldir)'),
(474208, 3, 4742, 4, 0, 15, 'The North Sea Kraken', 'The ships the two elven orders sent north were caught and held in the strait by a Kvaldir raiding vessel, and worse followed: the raiders have found a way to call up the dreaded kraken that lives beneath the North Sea. Kvaldir deepcallers chant the summoning, and the beast rises among the ships. If anyone aboard is to escape alive, says Crusader Silverdawn of the Argent Crusade, the kraken must be driven off and the ritual broken. He sends crusaders out on Argent hippogryphs with flaming spears to hurl at the beast, and blades for the deepcallers.', 'quest 14108 description and objectives; zone_areas 4760: North Sea Kraken 34925, Kvaldir Deepcaller 35092; smart_scripts 34925 (flaming spear hits; dies at low health with Kraken Tooth Explosion)'),
(474209, 3, 4742, 5, 0, 15, 'Kul the Reckless', 'Crusader Kul, a dwarf of the Argent Crusade, has a long habit of getting himself into trouble, and this time he has not gone alone. When the Cult of the Damned made camp at Deathspeaker''s Watch, on the ridge west of the tournament grounds, Kul gathered the tournament''s aspirants and led them against it without reinforcements. The cultists took them all with ease. Kul and his followers now sit in the cult''s black cages, and unless someone takes the keys from the cultists and sets them free, they will surely be sacrificed.', 'quests 14096 and 14142 descriptions; creature 34956 Kul the Reckless at 8459,1632 (Deathspeaker''s Watch, Icecrown); Captive Aspirant 34716; warcraft.wiki.gg/wiki/Kul_the_Reckless (dwarf, Argent Crusade, added 3.2.0)'),
(474210, 3, 4742, 6, 0, 15, 'Deathspeaker Kharos', 'The Cult of the Damned has redoubled its efforts to destroy the Argent Crusade and grown bold enough to mass its strength at Deathspeaker''s Watch, on the ridge west of the tournament grounds, under Deathspeaker Kharos. An attack on the grounds is coming, with every weapon the cult can bring to bear. High Crusader Adelard, who holds it his duty to set worthy quests before the crusade''s champions, is readying his men and the tournament''s valiants to defend the grounds. He would rather blunt the blow before it falls, and asks champions to lead that effort: to find Kharos and slay him.', 'quest 14105 description; npc_text 14659 (Adelard: as High Crusader it is his duty to task such men and women with worthy quests)'),
(474211, 3, 4742, 7, 0, 15, 'The Fate of the Fallen', 'The Argent Crusade is hardly the first force to challenge the Lich King, and the Scourge turns the spirits of those who fell before against it. They wander the Valley of Fallen Heroes, southwest of the tournament grounds between Aldur''thar and the Ironwall Rampart, and the ground there is littered with the soul crystals the Scourge uses to bind them. Crusader Silverdawn believes those heroes have more than earned their rest. He sends crusaders with a Light-blessed relic to gather the discarded crystals and, with the relic, bestow the blessing of peace upon the spirits.', 'quest 14107 description; item 47033 Light-Blessed Relic (start item of 14107)'),
(474212, 3, 4742, 8, 0, 15, 'Battle Plans of the Kvaldir', 'Now and then a Kvaldir raider on Hrothgar''s Landing is found carrying orders, and they show that the raiders look far beyond Northrend. With them is a map of the Eastern Kingdoms and Kalimdor with major settlements marked, and the orders set out a series of devastating raids drafted by the Kvaldir captains. The attacks are to begin once Mistcaller Yngvar has consulted the Heart of the Mists. Taking that omen from the Mistcaller''s Cave on the western side of the island might delay them, and the orders must be carried to Justicar Mariel Trueheart, seneschal of the tournament.', 'quest 24442 description and objectives; item 49676 Kvaldir Attack Plans (starts 24442), dropped by Kvaldir Reaver 34838 and Kvaldir Mist Binder 34839 (5 percent); gameobject 201367 Heart of the Mists at the cave (10186,1182, posarea 4742), loot item 49678; creature_template 33817 subname Seneschal of the Argent Tournament; warcraft.wiki.gg/wiki/Kvaldir (Kvaldir Attack Plans added in patch 3.2.2, never followed up)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(474202, 1, 0, 255, 'The horn brought the Sea Reaver out of the mist, demanding to know who dared challenge Drottinn Hrothgar, king of the seas, and in the circle of statues he was cut down. Adelard expects his death to set the Kvaldir fighting among themselves, and means the crusade to use the time it buys.', 'creature_text 34980 group 0 (You dare to challenge Drottinn Hrothgar, king of the seas?); smart_scripts 34980 (Cloud Aura on appearing); quest 14101 reward text'),
(474203, 1, 0, 255, 'Revealed by the charm, the mistcaller cried that his foe could never stop the Kvaldir and turned the choking mist on his foes, but he was slain in his own cave. Adelard counted it valuable time bought to move against the raiders and free the seas of them.', 'creature_text 34965 group 0 (Foolish, you cannot stop the Kvaldir!); smart_scripts 34965 (Mist of Strangulation); quest 14102 reward text'),
(474204, 1, 0, 255, 'The banner did its work, and Ornolf came out to fight and died on the deck of Bor''s Fury. His crew will want to avenge him, Adelard warns, but without him they will be easier to defeat, and the crusade must live to carry out its true mission: to rid Icecrown of the Scourge and every other evil.', 'quest 14104 reward text'),
(474205, 1, 0, 255, 'Much of the stolen meat was carried back from the island, a little worse for wear but still fit to eat, and the crusaders were glad to hear that some of the lost ship''s cargo had been saved.', 'quests 14074 and 14143 reward text'),
(474205, 2, 0, 255, 'Champions crossed the strait and cut down the raiders on their own ground, showing the Kvaldir that the tournament will not be threatened. The order that sent them took the deed as proof that it, and not its rival, stands truest beside the Argent Crusade.', 'quests 14080 and 14140 completion and reward text'),
(474206, 1, 0, 255, 'As the rites were read over each body, the villager''s spirit rose from it and slipped away, free of the mist at last. The prayer book was returned to the one who lent it, with a word for the confessor whose teaching had sent it out.', 'smart_scripts 34852 (on Read Last Rites: quest credit, cast 66412, despawn); smart_scripts 34888 Tualiq Spirit (on summon: spirit particles, rise up); quests 14077 and 14144 reward text'),
(474207, 1, 0, 255, 'Aboard the Firehawk the boarders were cut down, and the Kvaldir learned that the Sunreavers will not suffer such attacks. Girana the Blooded is pleased with the work, but she knows the fight for the strait goes on.', 'quest 14136 reward text'),
(474207, 2, 0, 255, 'Many of the Wavecrest''s crew owe their lives to those who fought beside them on her deck. Even so, Narasi Snowdawn has to admit that things at sea are worse than the Silver Covenant first thought.', 'quest 14152 reward text'),
(474208, 1, 0, 255, 'Flaming spears struck the kraken again and again and the deepcallers fell, and Silverdawn judged that it may have bought the sailors just enough time to escape. He hopes that next time the Silver Covenant and the Sunreavers will listen before charging headlong at the enemy.', 'quest 14108 reward text'),
(474208, 2, 0, 255, 'One kraken did not escape the spears, and it left behind a whole tooth, a rare find, which was carried to Silverdawn as proof. With the beast no longer harrying the ships, he reasons, the Kvaldir will have no choice but to retreat.', 'quest 14095 description and reward text; item 46955 Kraken Tooth (starts 14095); smart_scripts 34925 events 2-3 (Kraken Tooth Explosion, then dies)'),
(474209, 1, 0, 255, 'The keys were found and the cages opened. Kul came out declaring that the cultists had been seconds from strapping him to an altar and drawing out his soul, and he and the aspirants escaped the camp with their lives. It is far from the first time someone has had to save Kul from himself.', 'creature_text 34956 group 0 (spoken when his cage is opened); quests 14096 and 14142 reward text'),
(474210, 1, 0, 255, 'Kharos was found in his camp and slain. Adelard hailed the champion who did it as an example to all who have gathered beneath the crusade''s banner, and as proof that together they will show the Scourge it cannot defeat them.', 'quest 14105 reward text'),
(474211, 1, 0, 255, 'Blessed, the spirits ceased to fight and woke as if from a nightmare: some had dreamt they were fighting their own friends, and others asked only to rest. Silverdawn was moved to think on his own fate. Should he fall, he would want the same done for him, rather than force his brothers to slay him again and again.', 'creature_text 32149 group 0 (spoken on the Blessing of Peace, smart_scripts 3214900); quest 14107 reward text'),
(474212, 1, 0, 255, 'The Heart of the Mists proved to be a seeing crystal. Mariel took it and the orders, and judged that the theft would not slow the Kvaldir for long, but that it had bought time enough to warn the leaders of the Horde and the Alliance of the attacks to come.', 'quest 24442 reward text');
